corrected_code:
const Hapi = require('@hapi/hapi');
const Joi = require('joi');
const DeviceModel = require('../models/deviceMongoose');

const server = Hapi.server({ port: 3001 });

server.route({
  method: 'PATCH',
  path: '/v1/fleet/devices/{macAddress}/telemetry',
  options: {
    auth: 'bearer-token',
    validate: {
      params: Joi.object({
        macAddress: Joi.string().regex(/^([0-9A-Fa-f]{2}[:-]){5}([0-9A-Fa-f]{2})$/).required()
      }),
      payload: Joi.object({
        heartbeatIntervalSec: Joi.number().min(5).max(3600).required()
      })
    }
  },
  handler: async (request, h) => {
    const { macAddress } = request.params;
    const { heartbeatIntervalSec } = request.payload;
    const callerFleetId = request.auth.credentials.fleetId;

    // Constrain query to both MAC address and caller's fleetId
    const updatedDevice = await DeviceModel.findOneAndUpdate(
      { macAddress, fleetId: callerFleetId },
      { $set: { heartbeatIntervalSec, modifiedAt: new Date() } },
      { new: true }
    );

    if (!updatedDevice) {
      return h.response({ error: 'Device not found or not owned by your fleet' }).code(404);
    }

    return h.response({ success: true, device: updatedDevice }).code(200);
  }
});
